<?php
require_once __DIR__.'/../config/constants.php';require_admin();$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);if(!$id){redirect('admin/manage-admin.php');}$stmt=db()->prepare('SELECT id,full_name,username FROM tbl_admin WHERE id=?');$stmt->execute([$id]);$row=$stmt->fetch();if(!$row){flash('error','Admin not found.');redirect('admin/manage-admin.php');}
if(is_post()){verify_csrf();$name=trim((string)($_POST['full_name']??''));$username=trim((string)($_POST['username']??''));if(mb_strlen($name)<2||mb_strlen($username)<3){flash('error','Please enter valid details.');}else{$stmt=db()->prepare('SELECT id FROM tbl_admin WHERE username=? AND id<>?');$stmt->execute([$username,$id]);if($stmt->fetch()){flash('error','Username already exists.');}else{$stmt=db()->prepare('UPDATE tbl_admin SET full_name=?,username=? WHERE id=?');$stmt->execute([$name,$username,$id]);flash('success','Admin updated.');redirect('admin/manage-admin.php');}}}
$pageTitle='Edit Administrator';include __DIR__.'/partial/menu.php';?>
<div class="admin-title"><h1>Edit Administrator</h1></div><div class="panel admin-form"><form method="post"><?= csrf_field() ?><div class="field"><label>Full name</label><input class="input" name="full_name" value="<?= e($_POST['full_name']??$row['full_name']) ?>" required></div><br><div class="field"><label>Username</label><input class="input" name="username" value="<?= e($_POST['username']??$row['username']) ?>" required></div><br><button class="btn btn-primary">Save changes</button></form></div><?php include __DIR__.'/partial/footer.php';?>
